insert into public.products (seller_id, name, description, category, price, stock, image_url, approved, featured, created_at) values
  ('d0d0d0d0-0000-4000-8000-000000000005', 'مضرب احترافي كربون 7 طبقات', 'خشب 5 طبقات مع طبقتين كربون، سريع وثابت للاعب الهجومي. يأتي بدون أسطح.', 'rackets', 3450, 6, 'demo/p-racket-pro.jpg', true, true, now() - interval '0 days'),
  ('d0d0d0d0-0000-4000-8000-000000000005', 'مضرب جاهز للمبتدئين', 'مضرب كامل بأسطح معتمدة، خفيف وسهل التحكم. مثالي للمدارس والمبتدئين.', 'rackets', 650, 25, 'demo/p-racket-starter.jpg', true, true, now() - interval '2 days'),
  ('d0d0d0d0-0000-4000-8000-000000000005', 'كرات تدريب 3 نجوم (6 كرات)', 'كرات بلاستيك ABS 40+ معتمدة للمباريات، ارتداد ثابت وعمر طويل.', 'balls', 240, 60, 'demo/p-balls.jpg', true, false, now() - interval '4 days'),
  ('d0d0d0d0-0000-4000-8000-000000000005', 'سطح مضرب عالي الدوران', 'سطح هجومي بإسفنجة 2.1 مم، دوران عالٍ وتحكم ممتاز في التوب سبين.', 'rubbers', 1350, 15, 'demo/p-rubber.jpg', true, false, now() - interval '6 days'),
  ('d0d0d0d0-0000-4000-8000-000000000004', 'تيشيرت بينجو الرياضي', 'قماش خفيف يمتص العرق، مقاسات من S إلى XXL. متوفر بالأزرق.', 'clothing', 450, 40, 'demo/p-tshirt.jpg', true, true, now() - interval '8 days'),
  ('d0d0d0d0-0000-4000-8000-000000000004', 'حذاء تنس طاولة خفيف', 'نعل مطاطي لا يترك أثرًا، ثبات عالٍ في الحركة الجانبية.', 'shoes', 1900, 12, 'demo/p-shoes.jpg', true, false, now() - interval '10 days'),
  ('d0d0d0d0-0000-4000-8000-000000000004', 'حقيبة مضارب مزدوجة', 'تتسع لمضربين و6 كرات، مع جيب للمنشفة وحزام كتف.', 'bags', 520, 20, 'demo/p-bag.jpg', true, false, now() - interval '12 days'),
  ('d0d0d0d0-0000-4000-8000-000000000005', 'طاولة قابلة للطي للمنزل', 'طاولة مقاس رسمي بعجلات وقفل أمان، سطح 19 مم. التوصيل داخل القاهرة والجيزة.', 'tables', 18500, 3, 'demo/p-table.jpg', true, false, now() - interval '14 days'),
  ('d0d0d0d0-0000-4000-8000-000000000004', 'شبكة وحامل بمشبك', 'شبكة قابلة لضبط الارتفاع والشد، تركب على أي طاولة حتى 5 سم.', 'accessories', 380, 18, 'demo/p-net.jpg', true, false, now() - interval '16 days'),
  ('d0d0d0d0-0000-4000-8000-000000000004', 'منشفة قطنية للاعبين', 'منشفة صغيرة سريعة الجفاف بشعار بينجو.', 'accessories', 150, 30, 'demo/p-towel.jpg', false, false, now() - interval '18 days');

